 "content": "from collections import Counter


def transform(grid):
    """Decode the sparse colored junction lattice into its cell-color grid."""
    counts = Counter(v for row in grid for v in row)
    common = {color for color, _ in counts.most_common(2)}
    fill = counts.most_common(1)[0][0]

    knot_rows = [r for r, row in enumerate(grid)
                 if any(v not in common for v in row)]
    knot_cols = [c for c in range(len(grid[0]))
                 if any(grid[r][c] not in common for r in range(len(grid)))]

    result = []
    for r0, r1 in zip(knot_rows, knot_rows[1:]):
        out_row = []
        for c0, c1 in zip(knot_cols, knot_cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            if corners[0] not in common and all(v == corners[0] for v in corners):
                out_row.append(corners[0])
            else:
                out_row.append(fill)
        result.append(out_row)
    return result
